package com.academy.lms.review;import com.academy.lms.security.CurrentUser;import com.academy.lms.common.api.PageResponse;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController public class ReviewController{private final ReviewService service;public ReviewController(ReviewService s){service=s;}@PostMapping("/api/reviews")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasRole('STUDENT')")ReviewDtos.View create(@Valid@RequestBody ReviewDtos.Create r,Authentication a,HttpServletRequest h){return service.create(CurrentUser.id(a),r,h);}@GetMapping("/api/courses/{id}/reviews")PageResponse<ReviewDtos.View> list(@PathVariable UUID id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return PageResponse.from(service.list(id,page,size));}@PutMapping("/api/reviews/{id}")@PreAuthorize("hasRole('STUDENT')")ReviewDtos.View update(@PathVariable UUID id,@Valid@RequestBody ReviewDtos.Update r,Authentication a,HttpServletRequest h){return service.update(CurrentUser.id(a),id,r,h);}@DeleteMapping("/api/reviews/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id,Authentication a,HttpServletRequest h){service.delete(CurrentUser.id(a),isAdmin(a),id,h);}@PostMapping("/api/reviews/{id}/moderate")@PreAuthorize("hasAnyRole('INSTRUCTOR','ADMIN')")ReviewDtos.View moderate(@PathVariable UUID id,@Valid@RequestBody ReviewDtos.Moderate r,Authentication a,HttpServletRequest h){return service.moderate(CurrentUser.id(a),isAdmin(a),id,r,h);}private boolean isAdmin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));}}
